            "kind": "read",
            "h": "같은 고백 위에서 시작하는 이야기",
            "t": "이 책은 1517년부터 1750년 무렵까지, 서쪽 교회 안에서 개혁을 바라던 목소리가 여러 줄기로 갈라져 흐르게 된 이야기를 따라갑니다. 흔히 쓰는 '종교개혁'은 뒷날 붙은 이름이어서, 루터 자신도 이 말을 거의 쓰지 않았다고 합니다. 한 번의 개혁이 아니라 여러 개혁이 있었다고 부르는 학자도 있어서, 이 이름에는 한계가 있습니다.¹\n\n그 길에서 교회들은 서로 크게 다투게 되지만, 모두 같은 믿음의 바닥 위에서 출발했습니다. 루터교회는 아우크스부르크 신앙고백 1조에서 하나님이 한 분이시고 세 위격(하나님 안에서 구별되는 세 분)으로 계신다는 니케아 공의회의 가르침을 참되다고 말했습니다. 가톨릭의 트렌트 공의회는 1546년 셋째 회기에서 니케아-콘스탄티노플 신경(4세기에 정해진 믿음의 요점)을 모든 신자가 함께 서는 바탕으로 읽었고, 성공회의 39개조 8조와 개혁교회의 벨직 신앙고백 9조도 같은 신경을 받아들입니다.²\n\n| 교회 | 자기를 설명한 글 | 이어 받은 고백 |\n| --- | --- | --- |\n| 루터교 | 아우크스부르크 신앙고백 1조(1530) | 니케아 공의회가 말한 하나님의 하나 됨과 세 위격이 참되다고 말함 |\n| 가톨릭 | 트렌트 공의회 3차 회기의 신앙 선언(1546) | 로마 교회가 쓰는 신경을 모든 신자가 함께 서는 바탕으로 선언하고 니케아-콘스탄티노플 신경을 읽음 |\n| 성공회 | 39개조 8조(1563, 1571) | 니케아 신경, 아타나시우스 신경, 사도신경 세 신경을 온전히 받아들인다고 말함 |\n| 개혁교회 | 벨직 신앙고백 9조(1561) | 성경이 삼위일체를 증언한다고 말하고 같은 세 신경을 받아들임 |\n\n동쪽의 정교회도 니케아-콘스탄티노플 신경을 예배에서 읽으므로, 서쪽 교회들이 갈라진 뒤에도 이 신경은 여러 교회가 함께 받아 온 글로 남아 있습니다. 이 책의 모든 과는 이 같은 고백 위에서 읽습니다.²",
