            "h": "면죄부 앞에서",
            "t": "1515년 3월 교황 레오 10세는 로마의 성 베드로 대성당을 새로 짓는 일을 돕는 면죄부 교서를 냈습니다. 마인츠와 마그데부르크의 대주교였던 알브레히트의 지역에서는 설교가 1516년 말 무렵 시작되어 1517년까지 이어졌고, 도미니코회 설교자 요한 테첼이 그 가운데 이름이 알려진 설교자입니다.³\n\n가톨릭교회가 자기 입으로 하는 설명은 이렇습니다. 죄를 용서받은 뒤에도 정화받아야 할 몫이 남는다고 보고, 교회는 그리스도의 공로와 성도들의 기도와 선행이 보물처럼 쌓여 있다고 말합니다. 교회가 맺고 푸는 권한으로 신자를 위해 그 몫을 덜어 달라고 하나님께 청하는 일이 면죄부입니다. 1563년 트렌트 공의회는 이 권한이 교회에 있음을 밝히면서도, 돈을 노린 거래는 모두 없애라고 정했습니다.⁴\n\n루터는 이 설교를 보고 질문을 던졌습니다. 회개를 하나의 거래로 바꿀 수 있는가, 교회의 참된 보물은 복음이 아닌가, 가난한 이웃을 돕는 일이 더 낫지 않은가 하는 물음입니다. 또 면죄부를 사면 구원이 확실해진다고 믿는 사람들이 생기는 것을 걱정했습니다. 아래 표는 두 설명을 판정 없이 나란히 놓은 것입니다.⁵\n\n| 물음 | 가톨릭교회가 자기를 설명하는 말 | 루터의 질문(95개조와 편지) |\n| --- | --- | --- |\n| 회개와 벌 | 면죄부는 고해성사로 용서받은 죄에 남는 벌과 이어진 일이다. 신자는 참고 견디는 일, 자비의 행위, 기도, 절제로 그 몫을 받아들인다 | 주님이 회개를 말씀하신 것은 신자의 삶 전체가 회개이기를 바라신 것이다(1조) |\n| 교회의 보물 | 교회의 보물은 그리스도의 공로이고, 성모와 성도들의 기도와 선행도 여기에 속한다 | 교회의 참된 보물은 하나님의 영광과 은혜를 알리는 거룩한 복음이다(62조) |\n| 돈과 거래 | 트렌트 공의회: 교회에 이 권한이 있다. 돈을 노린 거래는 없애고 절제하여 베푼다 | 가난한 이에게 주는 것이 면죄부를 사는 것보다 낫다(43조). 면죄부를 사면 구원이 확실해진다고 믿게 될까 걱정한다(편지) |\n| 누가 어디까지 면하는가 | 교회가 그리스도께 받은 맺고 푸는 권한으로 신자를 위해 베푼다 | 교황이 면할 수 있는 것은 자기나 교회법이 정한 벌이고, 죄 자체는 하나님의 용서를 선언할 수 있을 뿐이다(5~6조) |"
