            "t": "로마서는 바울이 아직 가 보지 못한 로마의 성도들에게 보낸 편지입니다. 앞머리에서 바울은 자기가 전하는 복음이 하나님의 아들에 관한 소식이라고 소개하고(1:1~4), 로마에 가서 그들과 함께 복음을 나누고 싶다고 말합니다(1:10~15).\n\n16~17절은 이 편지 전체의 주제를 밝히는 대목으로 자주 읽힙니다. 바울은 이 소식을 내놓기를 부끄러워하지 않는다고 하며, 복음은 믿는 누구에게나 구원에 이르게 하는 하나님의 힘이라고 합니다. 먼저 유대 사람에게 열려 있고, 이방 사람에게도 열려 있습니다. 유대 사람과 이방 사람이 함께 있던 로마의 교회를 마음에 두고 쓴 말입니다.\n\n17절의 '하나님의 의'(하나님이 사람을 바르다고 받아 주시는 일)는 이 편지의 열쇠 낱말이고, 이 받아 주심을 칭의라고 부릅니다. 이 복음 안에서 그 길이 환히 드러나는데, 그 길은 처음부터 끝까지 믿음으로 이어진다고 합니다. 바울은 하박국 2:4를 끌어 와, 하나님께 바르다고 받아들여진 사람은 믿음에 기대어 살아간다는 말씀으로 맺습니다.",
