            "t": "1521년 4월 루터는 황제 카를 5세가 연 보름스 제국의회(제국의 제후와 도시 대표가 모이는 회의)에 불려 나갔습니다. 이미 1월에 교황의 교서로 파문이 확정된 뒤였습니다. 두 번째 날 그는 성경이나 분명한 이성으로 틀렸음이 밝혀지지 않는 한 자기 글을 취소할 수 없다는 뜻을 밝혔고, 5월에 황제의 이름으로 나온 칙령은 그를 교회를 어지럽히는 사람으로 규정하며 그의 글을 읽고 펴내는 일을 막았습니다.¹\n\n그를 아끼는 사람들은 루터를 바르트부르크 성으로 데려가 숨겼고, 루터는 거기서 열 달쯤 머물렀습니다. 그동안 신약 성경을 독일어로 옮겼고, 독일어 신약 성경은 1522년에, 전체 성경은 1534년에 나왔습니다.¹ 독일어 성경이 퍼지면서 말씀을 접하는 자리가 가정의 식탁으로까지 넓어졌다고 설명됩니다.²\n\n루터는 1529년에는 집안의 어른이 가정에서 가르칠 수 있는 짧은 교리문답을 냈고, 찬송을 지어 예배와 집안에서 부르게 했다고 합니다.²\n\n| 때 | 일 |\n| --- | --- |\n| 1521년 1월 | 교서 『데켓 로마눔 폰티피켐』으로 파문이 확정됨 |\n| 1521년 3월 | 황제 카를 5세가 루터를 보름스 제국의회에 부르고 오가는 길의 안전을 보장함 |\n| 1521년 4월 16일 | 루터가 보름스에 도착함 |\n| 1521년 4월 17일 | 자기 이름으로 나온 책들이 자기 것임을 인정하고, 생각할 하루를 청함 |\n| 1521년 4월 18일 | 성경이나 분명한 이성으로 틀렸음이 밝혀지지 않는 한 취소할 수 없다는 뜻을 밝힘 |\n| 1521년 5월 | 황제의 이름으로 보름스 칙령이 나옴. 루터를 교회를 어지럽히는 사람으로 규정하고 그의 글을 읽고 펴내는 일을 금함 |\n| 1521년 5월~1522년 3월 | 루터가 바르트부르크 성에 머묾 |\n| 1522년 | 루터의 독일어 신약 성경이 나옴(전체 성경은 1534년) |\n| 1524~1525년 | 독일의 농민 전쟁. 루터는 이 일을 두고 농민과 제후에게 글을 썼음 |",
