            "h": "본문의 자리",
            "t": "에베소서 2장 앞부분(1~7절)은 허물과 죄로 죽은 것과 같던 사람들을 하나님이 그리스도와 함께 살리셨다고 말합니다. 바울은 그 일을 '그리스도 예수 안에서' 베푸신 하나님의 풍성한 호의로 소개합니다.\n\n8~9절은 이 이야기를 되짚어 줍니다. 여러분이 구원을 받은 것은 하나님이 베푸신 호의 덕분이고, 그 호의를 받아 누리는 길이 믿음이라고 합니다. '구원을 받았다'는 말은 아직 얻으려고 애쓰는 일이 아니라 이미 건네받은 일로 쓰입니다. 이 구원은 사람이 만들어 낸 것이 아니라 하나님이 건네주신 선물이고, 사람이 한 일의 대가도 아니어서 누구도 내세울 수 없다고 합니다.\n\n10절은 우리가 하나님이 손수 빚으신 사람이라고 합니다. 선한 일은 하나님이 앞서 마련해 두신 길이고, 우리는 그리스도 안에서 그 길을 걷도록 새로 지음 받았다고 합니다. 이어지는 11~22절에서 바울은 유대 사람과 이방 사람 사이의 담을 그리스도께서 허무시고 둘을 한 몸으로 만드셨다고 말합니다.",
