            "t": "에베소서 2:8의 선물은 그리스도 안에서 주어진 선물입니다(2:5~7). 그리스도를 가리키는 자리가 바로 거기입니다. 루터는 1520년의 글에서 그리스도인이 모든 것 위에 자유로운 주인이면서 모든 사람을 섬기는 종이라고 썼습니다. 이 두 말은 2:8~9의 선물과 2:10의 선한 일이 어떻게 함께 가는지 생각하게 합니다.⁶\n\n아우크스부르크 신앙고백은 4조에서 믿음으로 받는 의로움을 말하고, 6조(새 순종)와 20조(선한 일)에서 선한 일을 따로 다룹니다. 『그리스도인의 자유』는 선한 일을 믿음에서 나오는 열매로 설명합니다. 선물을 받은 사람이 걷는 길이 선한 일로 이어진다고 읽은 것입니다.⁶\n\n우리와 같은 것은 웨스트민스터 신앙고백이 믿음 자체도 하나님이 주신 선물이라 하고(11장 1절), 그 믿음이 성령의 일이며 보통 말씀이 전해질 때 일어난다고 하며(14장 1절), 선한 일을 참되고 살아 있는 믿음의 열매이자 증거로 말하는 점입니다(16장 2절). 다른 것은 가톨릭교회와 루터교회가 칭의를 설명하는 말이 지금도 같지 않다는 점입니다. 두 교회는 1999년 공동 선언에서 기본 진리에 함께 서 있고 설명의 차이는 서로에게 열려 있다고 밝혔습니다(40항).⁶",
