            "t": "1519년 새해 첫날 훌드리히 츠빙글리는 스위스 취리히의 대성당에서 설교를 맡은 사제로 일을 시작했습니다. 취리히의 개혁은 왕이나 제후(영토를 다스리던 영주)가 아니라 도시 의회가 이끈 길이었습니다. 1523년 1월 29일 시 의회 앞에서 공개 토론이 열렸고, 츠빙글리는 자기 생각을 67개 조항으로 내놓았습니다.¹\n\n67개조의 첫 조항은 복음이 교회의 인정을 받아야 비로소 힘을 갖는다는 말을 물리칩니다. 열여덟째 조항은 그리스도께서 십자가에서 단 한 번 드린 제사로 충분하다고 하며, 미사는 그 제사를 기억하는 일이라고 말합니다. 시 의회는 그가 계속 설교하도록 두었고, 그 뒤 취리히의 개혁은 의회의 결정을 거치며 이어졌습니다.²\n\n츠빙글리는 1531년 10월 스위스 안의 가톨릭 지역들과 맞선 카펠 전투에서 세상을 떠났고, 그 뒤 하인리히 불링거가 취리히 교회를 이끌었습니다.³ 같은 도시에서 유아세례 대신 믿는 사람의 세례를 말하며 다른 길로 간 사람들이 있었는데, 이 이야기는 다음 과에서 읽습니다.",
