            "t": "1529년 10월 독일 마르부르크에서 루터와 츠빙글리를 비롯한 열 사람이 15개 조항을 함께 적었습니다. 하나님과 그리스도에 대한 고백, 믿음은 성령의 선물이며 복음을 들을 때 온다는 말, 어린아이에게도 세례를 주는 것이 옳다는 말을 포함한 열네 조항에 모두 뜻을 같이했습니다.⁴\n\n열다섯째 조항은 성찬(주님이 제자들과 나눈 마지막 식사를 따라 빵과 포도주를 나누는 예배)을 다룹니다. 빵과 포도주를 모두에게 주는 것, 성찬을 하나님이 세우셨다는 것, 약한 양심을 믿음으로 이끌려는 뜻이 있다는 것, 그리스도의 몸과 피를 영적으로 받는 일이 모든 그리스도인에게 필요하다는 것에는 함께 뜻을 모았습니다. 그러나 빵과 포도주 안에 몸과 피가 몸으로 계시는지는 합의하지 못했다고 적고, 서로에게 그리스도인의 사랑을 보이자고 했습니다.⁴\n\n아래 표는 여러 교회가 성찬을 설명한 글을 우리 말로 풀어 놓은 것입니다.⁵ 어느 설명이 옳은지는 가리지 않습니다.\n\n| 교회와 글 | 자기를 설명하는 말 |\n| --- | --- |\n| 루터교: 아우크스부르크 신앙고백 10조(1530), 루터의 소요리문답 성찬 부분(1529) | 주님의 만찬에서 그리스도의 몸과 피가 참으로 계시고, 먹는 사람들에게 나누어진다고 가르친다. 소요리문답은 성찬이 빵과 포도주 아래 있는 우리 주 예수 그리스도의 참된 몸과 피이고, 그리스도께서 직접 세우셔서 우리 그리스도인이 먹고 마시게 하신 것이라고 한다. 이 먹고 마심의 열매는 그리스도께서 \"너희를 위한 것\"이라고 하신 말씀에 있고, 거기서 죄 사함과 생명과 구원이 주어진다고 설명한다 |\n| 츠빙글리: 『신앙 해명』(Fidei ratio) 여덟째 항(1530, 황제 카를 5세에게 보낸 글) | 빵과 포도주는 그리스도의 몸과 피를 가리키는 표이다. 그리스도의 몸은 믿음으로 바라보며 감사하는 사람에게 믿음 안에서 눈앞에 계시고, 입으로 먹는 것이 아니라 믿음으로 영적으로 먹는다. 성찬은 감사의 식사이며 은혜를 믿는 마음을 북돋운다 |\n| 칼뱅: 『기독교 강요』 4권 17장(1559) | 빵과 포도주는 표이고, 그 표가 가리키는 그리스도 자신이 믿는 사람에게 참으로 주어진다. 그분의 몸은 하늘에 계시지만 성령께서 떨어진 거리를 이어 주신다 |\n| 가톨릭: 트렌트 공의회 13차 회기(1551), 『가톨릭교회 교리서』 1374·1376항 | 그리스도께서 빵과 포도주의 모양 아래 참으로, 실제로, 본질적으로 계신다. 빵과 포도주의 본질 전체가 몸과 피로 바뀌고, 교회는 이 변화를 화체(본질의 변화)라고 부른다 |\n| 정교회: 1672년 예루살렘 회의 17조 | 빵과 포도주가 그리스도의 참된 몸과 피로 바뀐다고 고백한다. 이 변화를 가리키는 말(화체로 옮기는 낱말)을 쓰면서도, 그 말로 방식이 설명되는 것은 아니고 어떻게 그렇게 되는지는 사람이 헤아릴 수 없다고 한다 |\n| 개혁교회: 웨스트민스터 신앙고백 29장 1절, 7절(1647) | 주님이 세우신 만찬은 십자가의 제사를 기념하고 그 은택을 인 치며 믿는 사람을 자라게 한다. 믿는 사람은 몸과 살의 방식이 아니라 영적으로, 그러나 참으로, 믿음으로 십자가에 달리신 그리스도와 그 은택을 받는다 |",
