            "h": "제네바에서",
            "t": "1536년 칼뱅은 바젤에서 『기독교 강요』 초판을 냈고 제네바에서 개혁을 돕게 되었습니다. 1538년 제네바를 떠났다가 1541년 돌아왔습니다. 질문과 대답으로 믿음을 가르치는 제네바 요리문답은 1542년 프랑스어로, 1545년 라틴어 판으로 나왔습니다. 1559년 『강요』 최종판이 나왔고, 칼뱅은 1564년 5월에 세상을 떠났습니다.⁶\n\n1553년 제네바에서 미카엘 세르베투스가 삼위일체를 부정하는 글로 재판을 받고 10월에 처형되었습니다. 그는 그해 프랑스 비엔의 가톨릭 법정에서도 고발되어 감옥에서 달아났고, 결석 재판에서 사형 판결을 받은 사람이었습니다. 비엔의 재판은 제네바에 살던 기욤 드 트리의 편지에서 시작되었다고 전해집니다. 제네바에서는 시의 관리들이 그를 붙잡았고 칼뱅의 요청이 있었으며, 판결은 시 의회가 내렸습니다.⁷\n\n그 시대에는 가톨릭과 개신교의 여러 곳이 신성모독(하나님을 모독하는 죄)을 엄하게 벌했고, 비엔과 제네바가 같은 사람에게 같은 결과를 말한 것도 그 한 모습입니다. 그러나 이 일을 두고 이미 반대하는 글이 나왔고, 카스텔리오가 썼다고 알려진 글 모음이 그 하나입니다. 1903년 제네바에는 이 일을 돌아보는 속죄 기념비가 세워졌습니다.⁷"
