            "kind": "read",
            "h": "처벌과 뒷날의 돌아봄",
            "t": "아래 표는 재세례파가 걸어온 길과 그들이 받은 처벌, 그리고 훗날 교회들이 이 일을 돌아본 일을 때와 곳을 중심으로 정리한 것입니다.⁴\n\n| 때 | 곳 또는 자리 | 일 | 뒤에 남은 사실 |\n| --- | --- | --- | --- |\n| 1525년 1월 | 취리히 근처 | 믿음을 고백한 어른이 세례를 받는 모임이 시작됨 | 시 의회는 이 모임을 막는 길로 나아감 |\n| 1526년 3월과 1527년 1월 | 취리히 | 시 의회가 다른 사람에게 세례를 주는 사람을 사형으로 벌하겠다고 정함. 이듬해 1월 펠릭스 만츠의 처형을 승인함 | 처벌한 쪽은 츠빙글리의 개혁을 따르던 도시의 의회였음 |\n| 1527년 2월 | 슐라이트하임 | 일곱 조항의 신앙고백이 나옴 | 세례, 공동체의 훈계, 세상 권세의 칼, 맹세 같은 일을 다룸 |\n| 1527년 5월 | 네카어 강가의 로텐부르크 | 미하엘 자틀러가 처형됨 | 가톨릭 군주 가문인 합스부르크의 오스트리아가 다스리던 땅이었음 |\n| 1529년 4월 | 슈파이어 | 제국의회의 결정에 재세례를 벌하는 조항이 들어감 | 사형을 요구한 이 제국의 명령을 따르지 않은 영방도 있었다고 뒷날의 보고서는 적음 |\n| 16세기 | 작센 선제후령, 베른, 티롤 | 루터를 따라 개혁한 작센 선제후령, 스위스에서 개혁을 받아들인 도시 베른, 가톨릭 군주가 다스린 티롤에서 모두 재세례파가 처형됨 | 뒷날의 보고서는 가톨릭 군주와 루터를 따른 영방과 개혁을 받아들인 도시의 권력이 모두 이 일에 참여했다고 적음 |\n| 1534~1535년 | 뮌스터 | 재세례파의 한 무리가 도시를 장악함 | 이 일로 재세례파 전체가 더 큰 의심을 받음. 다른 재세례파는 이 일을 거절함 |\n| 1536년 이후 | 네덜란드와 북독일 | 메노 시몬스가 재세례파에 합류해 폭력을 거절하는 모임들을 이끎 | 뮌스터 뒤에도 평화의 길을 걷는 모임들이 이어짐 |\n| 2003~2004년 | 가톨릭과 메노나이트의 대화 | 5년의 대화 끝에 공동 보고서가 나옴(2004년 봄 발표) | 가톨릭 쪽이 과거에 한 일도 이 대화에서 다루어졌다고 전해짐 |\n| 2004년 6월 | 취리히 | 취리히의 교회와 재세례파 후손들의 화해 모임이 열림 | 재세례파 후손들이 이 모임에 함께했다고 전해짐 |\n| 2009~2010년 | 루터교세계연맹 | 2009년 10월 이사회가 총회에서 메노나이트에게 용서를 구하자고 만장일치로 권함. 2010년 7월 슈투트가르트 총회가 옛 박해의 용서를 구함 | 루터교와 메노나이트가 함께 쓴 보고서 「치유하는 기억」에 따른 일 |\n\n표에서 보듯 처벌은 한 교회의 일이 아니었습니다. 개혁을 받아들인 취리히와 베른, 루터를 따라 개혁한 작센 선제후령, 가톨릭 군주의 땅들이 모두 재세례파를 벌했고, 1529년 슈파이어 제국의회의 결정에도 재세례를 벌하는 조항이 들어갔습니다. 훗날 취리히의 교회와 루터교세계연맹, 그리고 가톨릭과 메노나이트의 공동 보고서가 이 일을 돌아보았습니다.⁵\n\n뮌스터에서 일어난 일은 재세례파 가운데 한 무리가 한 일이었고, 다른 재세례파는 이를 거절했습니다. 그 뒤 모든 재세례파가 더 큰 의심을 받았고, 메노 시몬스는 폭력을 거절하고 평화를 말하는 모임들을 이끌었습니다."
