            "id": "cc04-r3",
            "kind": "read",
            "h": "믿는 사람의 세례와 아이의 세례",
            "t": "이 시대의 교회들은 세례를 가볍게 말하지 않았습니다. 다만 누가 언제 받는가를 두고 자기 말로 설명했습니다. 아래 표는 각 교회의 글을 우리 말로 풀어 놓은 것이고, 어느 쪽이 옳은지는 가리지 않습니다.⁶\n\n| 교회와 글 | 세례를 설명하는 말 | 지키려던 것 |\n| --- | --- | --- |\n| 재세례파: 슐라이트하임 신앙고백 1조(1527), 도르드레흐트 신앙고백 7조(1632) | 뉘우치고 삶을 바꾸었으며 그리스도 때문에 죄가 사해졌다고 믿는 사람이 스스로 청해 받는 세례. 도르드레흐트는 믿음으로 새로워진 사람이 물로 세례를 받는다고 말한다 | 믿음을 스스로 고백하는 삶, 세상 권세와 구분된 신앙 공동체(슐라이트하임 4조, 6조). 도르드레흐트 13조는 권세를 하나님이 세우신 것으로 존중하고 세금을 내며 위해 기도하라고 한다 |\n| 가톨릭: 트렌트 공의회 7차 회기(1547) 세례에 관한 정경(canon) 13조, 『가톨릭교회 교리서』 1250~1252항 | 아이도 교회의 믿음 안에서 세례를 받고, 세례는 되풀이하지 않는다. 13조는 아이가 자라서 다시 세례를 받아야 한다고 말하는 이를 물리친다 | 구원이 선물이라는 것(교리서 1250항), 2세기부터 이어 온 교회의 전통(1252항) |\n| 루터교: 아우크스부르크 신앙고백 9조(1530) | 세례는 구원에 필요하고 하나님의 은혜가 주어지는 길이다. 어린이도 세례를 받아야 하고, 세례로 하나님께 드려져 은혜 안에 받아들여진다. 이와 다르게 가르치는 재세례파를 물리친다 | 어린아이도 하나님의 은혜 아래 있다는 것 |\n| 개혁교회: 하이델베르크 요리문답 74문(1563), 벨직 신앙고백 34조(1561), 웨스트민스터 신앙고백 28장 3~4절(1647) | 아이도 하나님의 언약(하나님이 사람과 맺으신 약속)과 교회 안에 있고, 세례는 그 언약의 표이다(구약의 할례를 이은 것). 벨직 34조는 한 번 받은 세례로 만족하지 않는 재세례파의 잘못을 거부하고, 믿는 사람의 아이에게 세례를 주는 것을 정죄하는 이들을 물리친다. 웨스트민스터 28장은 믿는 부모의 자녀에게도 세례를 주고(4절), 물을 붓거나 뿌려 주는 것으로 바르게 베풀어진다고 한다(3절) | 하나님의 언약의 약속과 교회 공동체 |\n| 성공회: 39개조 27조, 38조(1563, 1571) | 세례는 새로 남의 표이고 교회에 접붙임을 받는 일이다. 어린아이의 세례는 교회에서 그대로 지키는 것이 그리스도께서 세우신 뜻에 가장 맞는다. 38조는 재산을 모두 함께 가져야 한다는 재세례파의 말을 물리친다 | 어린이를 교회에 접붙이는 것 |\n\n표의 글들은 서로 다르게 설명하면서 상대를 물리치는 말도 함께 적었습니다. 마르부르크에서 루터와 츠빙글리도 어린아이에게 세례를 주는 것이 옳다고 함께 적었습니다. 그 시대의 옛 로마 제국법은 다시 세례를 주는 일을 사형으로 벌할 죄로 다루었다고 뒷날의 보고서는 적습니다.⁶\n\n한쪽은 아이에게 주어지는 하나님의 약속에, 다른 쪽은 스스로 고백하는 믿음에 무게를 두었습니다. 두 쪽 모두 자기가 지키려는 뜻을 성경에서 찾았습니다."
