            "t": "바울이 세례를 말한 까닭은, 세례를 받은 사람의 삶이 그리스도의 죽음과 부활에 이어져 있음을 일깨우려는 것입니다. 믿음을 고백하고 세례를 청한 사람들과 아이에게 세례를 주는 교회들은 세례를 받는 때를 다르게 말했지만, 아래 두 글처럼 세례를 그리스도와 이어서 말했습니다. 이 책은 어느 쪽이 옳은지 가리지 않고, 처벌한 쪽과 처벌받은 쪽의 일을 여러 교회가 함께 진 짐으로 기억합니다.\n\n그리스도를 가리키는 자리는 6:3~4입니다. 슐라이트하임 신앙고백 1조는 세례를 받는 사람이 그리스도와 같은 자리에 묻히고 부활을 향해 걷는다고 쓰고, 웨스트민스터 신앙고백 28장 1절은 세례가 그리스도와 하나 됨의 표라고 말합니다.⁷\n\n우리와 같은 것은, 웨스트민스터 신앙고백 28장이 세례를 그리스도께서 세우신 것으로 말하고(1절), 믿는 부모의 자녀에게도 세례를 준다고 말하며(4절), 물을 붓거나 뿌려 주는 방식으로 바르게 베풀어진다고 말하는 점입니다(3절). 다른 것은 재세례파 교회들이 스스로 믿음을 고백하고 청하는 사람에게 세례를 준다고 말하고(슐라이트하임 1조), 가톨릭과 루터교와 성공회도 개혁교회처럼 아이에게 세례를 준다고 설명한다는 점입니다.⁷",
