            "kind": "read",
            "h": "각주",
            "t": "1. 그레벨과 만츠가 츠빙글리의 개혁을 너무 조심스럽다고 보고 시 의회와의 타협을 비판했으며, 어른의 세례를 가르쳐 재세례파라고 불린 것은 ZB 취리히. \"재세례파\"가 반대한 쪽이 붙인 깎아내리는 이름이었고 이들이 \"다시 세례를 준다\"는 말을 받아들이지 않고 자기 세례를 제대로 된 첫 세례로 보았다는 설명은 『치유하는 기억』(루터교세계연맹과 메노나이트세계협의회의 공동 연구 위원회 보고서, 2010).\n2. 1525년 1월 말에서 2월 초 취리히 근처의 세례와 시 의회의 조사는 GHDI 1525 심문기록(안내글이 의회가 이 세례들을 정죄했다고 설명함). 마르부르크 15개조 14조(유아세례)는 마르부르크 15개조(GHDI 판).\n3. 슐라이트하임의 일곱 조항(세례, 훈계, 빵을 뗌, 분리, 목자, 칼, 맹세)과 1527년 모임, 자틀러가 쓴 것으로 알려진 점은 슐라이트하임 신앙고백(GHDI 판, Estep 영역, *Anabaptist Beginnings*, 1976). 자틀러가 1527년 5월 네카어 강가의 로텐부르크에서 처형된 일과 그 땅이 합스부르크의 오스트리아가 다스리던 곳이었다는 점은 Goertz, 「Sattler, Michael」, *Neue Deutsche Biographie* 22권(2005); Willunat 자틀러 소개 글.\n4. 취리히에서의 일(1525~1527)은 『치유하는 기억』(1526년 3월 취리히 시 의회의 결정, 1527년 1월 만츠의 처형 승인); ZB 취리히; GHDI 1525 심문기록. 슈파이어 제국의회(1529년 4월)의 결정은 Fischer 2004; 『치유하는 기억』(1529년 제국의 명령과 이를 따르지 않은 영방). 작센 선제후령, 베른, 티롤의 일과 세 쪽 권력의 참여는 『치유하는 기억』. 뮌스터(1534년 2월 시 의회 선거, 1535년 6월 도시가 무너짐)는 Fischer 2004. 메노 시몬스(1536년 합류, 폭력을 거절함)는 Sprunger 2016; 도르드레흐트 신앙고백 14조(NOBTS 공개본).\n5. 2003년 가을에 끝난 가톨릭과 메노나이트 대화의 보고서(2004년 봄 발표)와 2004년 6월 26일 취리히의 화해 모임은 MWC 2004; RNS 2004. 2009년 10월 루터교세계연맹 이사회의 권고와 보고서의 이름은 『치유하는 기억』, 2010년 7월 22일 총회의 결정은 ELCA 뉴스 2010.\n6. 슐라이트하임 신앙고백 1조, 4조, 6조(GHDI 판). 도르드레흐트 신앙고백 7조, 13조(NOBTS 공개본). 트렌트 공의회 7차 회기(1547년 3월 3일)의 세례에 관한 정경 13조(Hanover 판, Waterworth 영역)와 『가톨릭교회 교리서』 1250~1252항(바티칸 공식 영문본). 아우크스부르크 신앙고백 9조(공개 영문본). 하이델베르크 요리문답 74문(CRC 공식 쪽). 벨직 신앙고백 34조(CCEL 공개본). 영국 교회 39개조 27조, 38조(영국 교회 공식 쪽). 웨스트민스터 신앙고백 28장 3절, 4절(공개 원문). 다시 세례를 주는 일을 옛 로마 제국법이 중한 죄로 다룬 점은 『치유하는 기억』. 표의 글은 모두 우리 말로 풀어 쓴 것이다.\n7. 슐라이트하임 1조(그리스도와 같은 자리에 묻힘, 부활의 길)는 슐라이트하임 신앙고백(GHDI 판). 웨스트민스터 신앙고백 28장 1절(그리스도와 하나 됨의 표, 새 삶), 3절(물을 붓거나 뿌림), 4절(믿는 부모의 자녀)은 공개 원문."
