            "t": "1553년 메리 1세가 즉위하자 영국 교회는 다시 로마의 교황과 이어졌고, 당시 '이단'이라 부르던 일을 벌하는 옛 법이 되살아났습니다. 1555년부터 1558년까지 개신교 신자들이 이 법으로 재판을 받아 일부는 목숨을 잃었습니다. 크랜머와 래티머와 리들리 같은 성직자도 있었고 보통 사람도 많았다고 합니다. 개신교 쪽에는 이들을 믿음을 지킨 사람들로 기억하는 전통이 있습니다.⁴\n\n1558년 엘리자베스 1세가 즉위하자 의회는 1559년 왕의 칭호를 머리가 아닌 최고 통치자로 정하고 고친 기도서를 쓰게 했습니다. 1563년에 정해 1571년에 확정한 39개조는 영국 교회가 자기를 설명한 글입니다.⁵\n\n같은 시대에 가톨릭 신자들도 재판을 받아 일부는 목숨을 잃었습니다. 1570년 교황 비오 5세가 교서로 여왕을 교회에서 내보낸다고 선언한 뒤 법이 무거워졌고, 반역죄로 처벌받은 사람 가운데 에드먼드 캠피언 같은 예수회 사제도 있었고 보통 신자도 있었다고 합니다. 가톨릭교회는 이들을 믿음을 지킨 순교자로 기립니다. 1970년 교황 바오로 6세는 잉글랜드와 웨일스의 순교자들을 성인으로 선포하며 그 자리에 온 성공회 사람들에게 인사했습니다.⁶ 아래 표는 세 교회의 글입니다.\n\n| 쟁점 | 영국 교회(39개조, 기도서) | 가톨릭(트렌트 교령, 바티칸 공의회, 1570년 교서) | 개혁교회(웨스트민스터 신앙고백) |\n| --- | --- | --- | --- |\n| 예배의 말 | 기도서 서문은 교회에서 읽고 부르는 것을 영어로 하여 알아듣고 덕을 세우게 한다고 밝힘. 39개조 24조는 알아듣지 못하는 말로 공적으로 기도하는 것이 성경과 옛 교회의 관습에 맞지 않는다고 함 | 트렌트 22차 회기(1562) 8장은 미사가 신자에게 큰 가르침을 주지만 모든 곳에서 모국어로 드리는 것은 알맞지 않다고 보았고, 사목자들이 미사 중에 읽은 말씀의 일부를 자주 풀이하라고 함. 제2차 바티칸 공의회의 전례 헌장(1963) 36항과 54항은 모국어를 쓰는 범위를 넓히되 기본은 라틴어 전례로 두고 그 범위는 교회 권위가 정한다고 함 | 21장 3절은 기도를 입으로 드린다면 알아듣는 말로 해야 한다고 함 |\n| 교회의 머리와 다스림 | 39개조 19조는 보이는 교회를 순수한 말씀이 선포되고 성례가 바르게 베풀어지는 신자의 모임이라 함. 37조는 왕에게 으뜸 통치의 권한이 있으나 말씀과 성례를 맡는 일을 왕에게 주는 것은 아니라고 함 | 1570년 교서는 하나의 거룩한 공교회가 베드로와 그 후계자인 로마의 주교에게 맡겨져 온전한 권한으로 다스려진다고 시작함 | 25장 1~2절은 보이지 않는 교회를 모든 시대의 택하신 사람들이 그리스도를 머리로 하여 모인 교회로, 보이는 교회를 참된 신앙을 고백하는 사람들과 그 자녀들로 말함 |"
