            "t": "에베소서는 교회가 그리스도 안의 한 몸이라는 말씀으로 가득한 편지입니다. 4장 11~16절은 그 몸이 어떻게 자라는지를 말합니다. 11절은 그리스도께서 어떤 이들을 사도와 예언자와 복음을 전하는 사람과 목자와 교사로 세우셨다고 합니다.\n\n12~13절은 이 직분을 주신 까닭을 말합니다. 믿는 사람들이 섬기는 일을 할 수 있도록 채우고 몸을 세우며, 믿음과 하나님의 아들을 아는 일에서 하나가 되어 성숙한 어른의 모습에 이르게 하려는 것입니다. 14절은 그렇게 자라지 못하면 어린아이처럼 이런저런 가르침의 바람에 이리저리 밀린다고 합니다.\n\n15~16절은 참된 말을 사랑으로 전하라고 하며, 자람의 방향이 머리이신 그리스도라고 합니다. 몸 전체가 그분께 이어져 있어서, 각 부분이 맡은 일을 하면서 서로 사랑하는 가운데 몸이 커 갑니다.",
