            "t": "이 책은 이 본문을 이 시대 모든 교회의 새로움에 이어 읽어 봅니다. 12~13절은 직분이 믿는 이들이 섬기는 일을 하도록 채우고 몸을 세우는 일이라 하고, 14절은 자라지 못한 교회가 흔들린다고 합니다. 트렌트가 설교와 신학교와 교리 교육을 말한 것도, 여러 교회가 요리문답과 기도서를 만든 것도 몸이 자라는 일을 돌보려는 마음과 닿아 있다고 읽을 수 있습니다.\n\n그리스도를 가리키는 자리는 15~16절입니다. 몸은 머리이신 그리스도를 향해 자라고, 몸이 세워지는 힘도 그분에게서 나옵니다. 교회의 새로움이 어디에서 오는지를 이 말씀이 알려 줍니다.\n\n우리와 같은 것, 다른 것. 웨스트민스터 신앙고백 25장 3절은 그리스도께서 보이는 교회에 직분과 말씀과 규례를 주셔서 성도를 모으고 온전하게 하신다고 말하며, 근거 구절에 에베소서 4:11~13이 있습니다. 가톨릭, 정교회, 성공회, 개신교의 교회들이 모두 에베소서를 성경으로 받습니다. 다른 것은 직분과 교회의 다스림을 설명하는 방식입니다. 트렌트 23차 회기는 사제직을 성사로 설명하고 주교가 사제보다 높은 자리라고 밝혔는데, 교회마다 달리 설명합니다. 이 책은 판단하지 않고, 우리 교회의 입장은 교역자와 나눕니다.⁷",
