            "kind": "read",
            "h": "각주",
            "t": "1. 1541년 레겐스부르크 회담(칭의에 관한 문안을 만들려 했으나 받아들여지지 않음)과 공의회를 열자는 앞선 요구는 Jedin 1957. 트렌트 공의회의 첫 회기(1545년 12월 13일, 바오로 3세)는 트렌트 교령 1차 회기.\n2. 트렌트 교령 5차 회기(1546년 6월 17일) 개혁에 관한 교령 2장(주교의 설교, 본당 사제의 가르침), 23차 회기(1563년 7월 15일) 개혁에 관한 교령 18장(신학교), 24차 회기(1563년 11월 11일) 개혁에 관한 교령 3장(방문)과 4장(설교와 아이들의 가르침), 25차 회기(1563년 12월 3~4일)의 마침과 비오 4세의 확인(1564년 1월 26일). 장 번호는 Schroeder 영역을 공개한 Hanover 판의 번호.\n3. 팜플로나의 부상과 읽은 책은 이그나티우스 자서전 1장. 『영신수련』의 첫 원리와 훈련의 짜임은 영신수련(Mullan 영역, 1914). 1491년 무렵의 출생, 1521년의 부상, 1534년 8월 15일의 서약, 1556년의 죽음은 O'Malley 1993. 1540년 9월 27일 바오로 3세의 『레기미니 밀리탄티스 에클레시에』와 예수회의 목적은 예수회 정관 1540.\n4. 데레사의 생애와 저서의 연도(1515, 1562, 1565, 1566, 1582, 1622, 1970)는 Vatican 데레사. 십자가의 요한(1542, 1567, 1568, 1577, 1578, 1591, 1726, 1926)은 Vatican 요한. 카를로 보로메오의 사목 방문과 교리 학교와 신학교와 1610년의 성인 선포는 Vatican 보로메오. 『로마 교리문답』(1566)은 로마 교리문답(표제 Catechismus ex decreto Concilii Tridentini ad parochos, 곧 본당 사제들에게); Jedin 1957.\n5. 트렌트 교령 6차 회기(1547년 1월 13일) 칭의 교령 5, 7, 8장(16장과 33개 조항). 아우크스부르크 신앙고백 4조. 웨스트민스터 신앙고백 11장 1~2절(1647 원문). 1999년 『칭의 교리에 관한 공동 선언』 14, 15~17, 40, 41항(루터교세계연맹 공식 영문본).\n6. 이름의 역사와 한계는 O'Malley 2000; Bireley 1999(제목에 \"반종교개혁의 재평가\"를 담았다). 쇄신과 방어의 구별은 Jedin 1946(『가톨릭 개혁인가 반종교개혁인가?』 소책자).\n7. 웨스트민스터 신앙고백 25장 3절; 트렌트 교령 23차 회기 교령."
