            "t": "서로 맞서던 제후와 도시들 사이에 평화를 세우려는 합의가 1555년 9월 아우크스부르크 제국의회에서 선포되었습니다. 1552년의 파사우 조약 뒤에 열린 신성 로마 제국(독일어권 땅을 중심으로 많은 제후와 도시로 이루어진 나라)의 의회였고, 황제는 카를 5세였으며 로마 왕 페르디난트가 합의를 알렸습니다.¹\n\n합의는 옛 신앙을 따르는 이들과 아우크스부르크 신앙고백을 따르는 이들이 신앙을 이유로 서로 전쟁하거나 폭력을 쓰지 않기로 했습니다. 다른 신앙을 가진 백성은 가족과 함께 재산을 정리하고 떠날 길이 열려 있었습니다. 교회의 높은 직분자가 옛 신앙을 떠나면 직분과 수입을 내려놓기로 했고, 1552년 파사우 조약 이전에 이미 넘어간 교회 재산은 그대로 두는 항도 있었습니다.¹\n\n그러나 이 두 고백 어느 쪽에도 속하지 않은 이들은 이 평화에 들지 않는다고 적었습니다. 개혁교회와 재세례파 교회들이 그러했습니다. 합의는 하나 됨이 이루어질 때까지 지키는 약속으로 정해졌습니다.¹",
