            "h": "표로 보는 평화 합의와 전쟁",
            "t": "아래 표는 합의를 맺은 때와 곳, 합의의 내용을 사실만 적은 것입니다. 이 싸움들에서 목숨을 잃은 사람의 수나 피해의 크기는 자료마다 크게 다르고, 기록한 사람의 자리에 따라 달라서 적지 않았습니다. 표의 일들이 정당했는지는 판단하지 않습니다.\n\n| 연도 | 일 | 합의의 내용(사실만) | 비고 |\n| --- | --- | --- | --- |\n| 1555 | 아우크스부르크 종교 평화 | 신성 로마 제국 안에서 루터교 쪽 제후와 가톨릭 쪽 제후가 서로를 인정하고 신앙을 이유로 서로 전쟁하지 않기로 했다. 개혁교회와 재세례파 교회들은 이 합의 밖이었다 | 합의문은 하나 됨이 이루어질 때까지의 약속이라고 적었다 |\n| 1562~1598 | 프랑스의 종교 전쟁 | 싸움이 여러 차례 이어졌다. 1572년 8월 파리의 생바르텔레미의 밤에 왕실 쪽 사람들과 도시의 민병도 나선 폭력이 일어나 여러 도시의 개신교인에게 번졌다. 1598년 낭트 칙령이 위그노(프랑스의 개혁교회 신자들)에게 정해진 곳에서 예배할 자유와 공직에 오를 길 같은 일부 권리를 주고, 가톨릭 예배가 중단되었던 곳에서는 되살렸다 | 싸움의 횟수는 학자마다 다르다. 칙령은 앙리 4세 때 나왔다 |\n| 1566~1648 무렵 | 네덜란드의 독립을 둘러싼 싸움 | 1566년 네덜란드에서 교회의 성상을 부수는 일이 널리 번졌고, 이어 에스파냐 왕이 알바 공을 보내 권위를 되찾으려 했으며 이에 맞선 싸움이 길게 이어졌다 | 시작과 끝은 학자마다 다르다 |\n| 1618~1648 | 30년 전쟁 | 1618년 5월 보헤미아의 프라하에서 시작해 여러 나라가 얽혔다. 1629년 3월 황제가 1552년 뒤 개신교 제후들이 가져간 교회 재산을 돌려주라는 칙령을 냈다. 1631년 5월 개신교 도시 마그데부르크가 가톨릭 쪽 군대에 점령되고 도시의 대부분이 불에 탔다. 1631년 10월 스웨덴군이 가톨릭 주교의 땅 뷔르츠부르크를 점령해 교회 재산이 몰수되거나 무거운 세금이 매겨졌고, 1632년 5월 뮌헨에 들어갔다. 바이에른 농민들이 맞서자 군대가 시골을 불태우며 쫓았고, 가톨릭 도나우 지방에는 스웨덴군에 대한 쓰라린 기억이 오래 남았다 | 가톨릭 프랑스가 루터교 스웨덴과 손잡은 일도 있었다. 스웨덴군과 황제군은 두 고백의 백성 모두에게 피해를 주었다고 랑거의 글은 적는다 |\n| 1648 | 베스트팔렌 평화 | 10월 뮌스터와 오스나브뤼크에서 조약을 맺었다. 아우크스부르크 평화를 다시 확인하고, 루터교와 가톨릭에 더해 개혁교회도 제국에서 인정했다. 교회 재산과 예배는 1624년 1월 1일의 상태를 기준으로 정했다. 이 세 고백 밖의 신앙은 제국에서 받아들이지 않는다고 적었다 | 다른 고백의 백성에게도 양심의 자유와 사사로운 예배의 길을 열었다 |\n| 1685 | 낭트 칙령 철회 | 루이 14세가 칙령을 거두었다. 개신교 예배당을 헐고 예배를 금했으며, 개종하지 않는 목사에게 두 주 안에 나라를 떠나라고 했다. 위그노가 프랑스를 떠났다 | 떠난 사람의 수는 자료마다 다르다 |\n\n표의 합의들은 모두 어떤 신앙을 어디까지 인정할지를 정한 글이었습니다. 프랑스의 칙령은 1598년 앙리 4세 때 나왔다가 1685년 루이 14세가 거두었고,² 제국의 조약들은 여러 나라를 끌어들인 30년의 싸움 끝에 1648년 10월에 맺어졌습니다.³\n\n한 번 맺은 합의가 오래가지 못한 곳도 있었고, 싸움 끝에 다시 확인한 곳도 있었습니다. 1685년에는 칙령이 거두어지기도 했습니다. 평화는 문서 한 장으로 끝나지 않고 여러 번 다시 약속해야 하는 일이었습니다."
