            "t": "이 싸움에서 아픔을 입은 쪽은 한쪽이 아니었습니다. 프랑스에서는 1561~1562년에 개신교 쪽 무리가 여러 곳에서 성당을 차지하고 성상과 제단을 부수었고, 사제와 수도자를 중심으로 일반 신자도 해를 입었습니다. 1572년 8월에는 왕실 쪽 사람들과 도시의 민병도 나선 가운데 폭력이 파리와 리옹, 오를레앙 같은 도시의 개신교인에게 번졌고, 책임이 어디에 얼마나 있는지는 학자마다 다르게 읽습니다. 제국에서는 1631년 개신교 도시 마그데부르크가 무너졌고, 같은 해 가톨릭 지역인 뷔르츠부르크와 이듬해 바이에른이 스웨덴군의 진격을 겪었습니다.⁴\n\n이 일들을 한데 묶어 \"종교 전쟁\"이라 부르는 이름은 뒷날의 것입니다. 그 시대 사람들도 싸움을 신앙과 이어 말했지만, 이 이름이 무엇을 보여 주고 무엇을 가리는지를 두고 학자들은 서로 다르게 읽습니다.⁵\n\n아래 표는 그 읽기들 가운데 일부를 나란히 놓은 것이며 어느 읽기가 옳은지는 판단하지 않습니다.\n\n| 읽는 사람 | 읽기 | 눈여겨보는 것 |\n| --- | --- | --- |\n| 데이비스(Davis 1973, 프랑스) | 종교 때문에 일어난 군중의 폭력이 단순한 비이성이나 계급 다툼이 아니라 종교와 정치의 전통에서 나온 나름의 논리를 가졌다고 읽는다. 군중이 설교하는 사람, 오염을 씻어 내는 사람, 관리처럼 행동했다고 본다 | 신앙과 공동체의 질서가 얽힌 모습 |\n| 윌슨(Wilson 2009, 30년 전쟁) | 서평은 이 책이 전쟁을 무엇보다 정치, 군사, 재정의 이야기로 풀고 종교의 말과 문화가 사건에 준 영향을 작게 본다고 읽는다. 서평자는 일부 다르게 읽어, 종교의 말, 특히 거룩한 전쟁의 말이 1630년대 중반까지 동맹과 백성을 모으는 데 크게 쓰였다고 본다 | 왕과 제후의 권력, 군대, 돈. 그리고 성직자의 설교와 신앙의 호소 |\n| 캐버노(Cavanaugh 2009) | 16세기에는 종교와 정치가 오늘처럼 나뉘어 있지 않았으므로 \"종교 전쟁\"이라는 이름이 뒷날의 눈이라고 본다. 가톨릭끼리 싸우고 가톨릭 프랑스가 루터교 스웨덴을 도운 일을 든다. 학자들이 종교의 비중을 달리 평가한다는 점도 쓴다 | 나라가 힘을 모으고 영토를 다지던 과정 |"
