            "t": "회의는 예배 지침과 교회 정치 규정, 신앙고백, 두 요리문답을 내놓았습니다. 의회는 1645년 1월 기도서를 쓰지 못하게 하고 예배 지침을 정했습니다. 신앙고백은 1646년 12월 의회에 올라갔고 1647년 4월에는 대목마다 성경 구절 근거를 붙인 판이 나왔습니다. 회의 기록에 남은 본회의만 천 번이 넘습니다.⁴\n\n받아들인 곳은 달랐습니다. 스코틀랜드 교회 총회는 1647년 8월 신앙고백을 받아들이면서 31장 2절은 아직 정리되지 않은 교회에만 해당한다는 설명을 붙였습니다. 영국 의회는 1648년에 교회의 처벌을 다룬 30장과 회의를 다룬 31장 같은 대목을 빼고 펴내게 했습니다. 소요리문답의 첫 물음은 사람이 사는 가장 큰 목적을 묻고, 하나님을 높이며 그분 안에서 오래 기뻐하는 것이라고 답합니다.⁵\n\n1649년 1월 찰스 1세가 처형되었고, 1660년 왕정이 돌아온 뒤 1662년의 통일령은 개정된 기도서를 쓰라고 요구해 이를 받아들이지 않은 목사들이 자리를 내놓았습니다. 그 수는 학자마다 크게 갈립니다.⁶ 감독제를 지키던 교회는 1640년대에 기도서를 쓰지 못했고, 청교도 목사들은 1662년에 자리를 잃었습니다. 두 쪽 모두 아픔을 겪은 시대였습니다.\n\n| 때 | 일 | 곳과 문서 |\n| --- | --- | --- |\n| 1643년 6월 12일 | 의회가 조례로 목사들의 모임을 부름 | 의회의 조례 |\n| 1643년 7월 1일 | 모임이 시작됨 | 웨스트민스터 사원 헨리 7세 예배당 |\n| 1643년 9월 25일 | 하원이 엄숙 동맹을 받아들임 | 잉글랜드와 스코틀랜드 |\n| 1645년 1월 | 기도서 대신 예배 지침을 쓰도록 정함 | 의회의 조례 |\n| 1646년 12월 4일 | 신앙고백을 의회에 올림 | 웨스트민스터 신앙고백 |\n| 1647년 4월 26일 | 성경 구절 근거를 붙인 판을 올림 | 웨스트민스터 신앙고백 |\n| 1647년 8월 27일 | 스코틀랜드 교회 총회가 신앙고백을 받아들임 | 31장 2절에 설명을 붙임 |\n| 1647년 10월~1648년 4월 | 대요리문답과 소요리문답을 올리고 성경 구절 근거를 붙임 | 대요리문답, 소요리문답 |\n| 1648년 | 영국 의회가 일부 장을 뺀 판을 펴내게 함 | 30장과 31장 등을 뺌 |\n| 1648년 7월 | 스코틀랜드 교회 총회가 두 요리문답을 받아들임 | 대요리문답, 소요리문답 |"
