            "h": "각주",
            "t": "1. 청교도라는 이름의 처음 쓰임과 뜻이 학자마다 갈린다는 점, 영국 교회 안에 머문 사람과 따로 모인 사람이 모두 있었다는 점은 Spurr 1998; Coffey & Lim 2008. 영국 내전의 시작과 끝(1642~1651)은 Spurr 1998. 엄숙 동맹은 1643년 9월 25일 하원이 받아들인 글이고 영국, 스코틀랜드, 아일랜드 교회의 믿음과 신앙고백과 다스림과 예배와 요리문답을 가깝게 하겠다는 맹세를 담았다(Gardiner 1906의 본문). 이 약속이 회의에 스코틀랜드 대표가 함께하게 된 바탕이었다는 설명은 Letham 2009; Van Dixhoorn 2012.\n2. 1643년 6월 12일 조례의 내용(주교의 다스림이 개혁에 걸림이 되고 나라에 짐이 된다는 의회의 판단, 의회가 물은 일만 의논함, 7월 1일 헨리 7세 예배당, 이름이 오른 사람들)은 소집 조례 1643(Firth와 Rait 1911, 180~184쪽). 조례가 왕의 동의 없이 의회가 낸 것이라는 점은 Spurr 1998. 왕이 1643년 6월에 의회의 조례를 따르지 말라고 알린 포고는 왕의 포고 1643.\n3. 모임이 처음 받은 일(39개조 고쳐 쓰기)과 10월의 명령은 Schaff 1931(7월 5일과 10월 12일의 의회 명령). 장로제와 독립파의 깊은 이견은 Walker 1983; Letham 2009. 표의 내용은 기도서 안수례 머리말(기도서 1662의 안수례 머리말)과 39개조 20·21·36조, 교회 정치 규정 1645와 교회 정치 조례 1648, 사보이 선언 1658의 교회 정치 부분(회중제). 1648년 조례가 영국에서 널리 자리 잡지 못했다는 설명은 Spurr 1998. 회의가 주로 웨스트민스터 사원 안의 예루살렘 방에서 모였다는 설명은 Van Dixhoorn 2012.\n4. 문서의 날짜(1646년 12월 4일, 1647년 4월 26일, 요리문답의 올림과 성경 구절 근거)는 Van Dixhoorn 2012의 문서 일람(5권). 기도서를 쓰지 못하게 한 1645년 1월의 조례는 기도서 폐지 조례 1645. 본회의가 천 번이 넘는다는 설명은 Van Dixhoorn 2012가 실은 회의록의 회기 번호(1~1163)에 따른다.\n5. 스코틀랜드 총회의 1647년 8월 27일 결의(31장 2절의 설명)와 1648년 7월의 요리문답 승인은 스코틀랜드 총회 1843. 영국 의회가 1648년에 30장과 31장과 20장 4절과 24장 일부를 뺀 판을 펴내게 한 일은 Schaff 1931. 소요리문답 1문은 소요리문답.\n6. 1649년 1월 찰스 1세의 처형은 Coffey & Lim 2008. 1662년 통일령과 개정 기도서, 자리를 내놓은 목사의 수는 칼러미의 집계(약 1,900명)와 매슈스가 고쳐 센 수(약 900명 남짓), 그보다 훨씬 적게 본 존 워커의 주장이 갈린다(Matthews 1934; Spurr 1998).\n7. 신앙고백 1장 2·6절과 31장 4절의 요지는 1647 원문(영어)에서 우리 말로 풀었다(31장 4절은 1647 원문과 한국 장로교 번호이고 미국 개정판은 3절이다). 가톨릭교회 교리서 80~82항은 바티칸 공식 영문본. 39개조 6·20·21조는 39개조 본문. 정교회가 성경과 전통의 관계를 스스로 설명하는 말은 Ware 1993."
