            "h": "본문의 자리",
            "t": "갈라디아서는 바울이 갈라디아 지역의 교회들에게 보낸 편지입니다. 이 교회들에는 율법의 요구를 지켜야 구원이 완전해진다는 생각이 퍼져 있었고, 바울은 5장에서 이에 맞서 말합니다. 5:1에서 바울은 자유가 그리스도께서 베푸신 것이라고 하며, 그 자유 위에 발을 딛고 서서 노예의 짐을 도로 지지 말라고 권합니다.\n\n5:13은 자유로 부르심을 받았다고 하면서 자유를 쓰는 두 길을 가려냅니다. 자유를 자기 욕심을 위한 핑계로 쓰는 길이 있고, 사랑으로 서로를 돌보는 길이 있습니다.\n\n5:14는 율법 전체가 한 말씀 안에 담긴다고 하며, 그 한 말씀을 이웃을 자기 몸처럼 아끼는 일이라고 말합니다. 그래서 이 본문에서 자유는 율법의 요구 앞에서 짐을 벗는 일이면서 이웃을 향해 열린 일입니다.",
