            "kind": "read",
            "h": "작은 모임에서 시작된 열망",
            "t": "독일의 목사 슈페너는 1675년 『경건한 열망』이라는 글을 펴내 교회가 새로워지는 길을 제안했습니다. 슈페너는 교회의 가르침이 삶으로 이어지고, 성경이 함께 읽히고 나누어지기를 바랐다고 전해집니다.¹ 뒷날 이런 흐름을 경건주의(믿음을 마음과 삶의 경건으로 이어 가려는 흐름)라고 불렀습니다.\n\n슈페너에게 영향을 받은 프랑케는 1690년대 독일 할레에서 가난한 아이들을 돌보는 학교를 시작했고, 이 일은 고아원과 여러 학교로 이어졌다고 전합니다.¹ 같은 흐름의 영향을 받은 귀족 진젠도르프는 작센 땅에 영지를 가지고 있었습니다.\n\n1722년 모라비아(지금의 체코 지방)에서 신앙 때문에 피난한 가족들이 이 영지에서 집을 짓기 시작했고, 이곳이 헤른후트가 됩니다. 1727년 여름 진젠도르프는 옛 형제 교회(보헤미아와 모라비아에서 이어 오던 교회)를 새롭게 한다는 생각을 내세웠고, 그해 8월 성찬 예배에서 공동체가 새로워졌다고 전합니다.²\n\n| 사람 | 때 | 한 일 |\n| --- | --- | --- |\n| 슈페너 | 1675년 | 『경건한 열망』을 펴냄 |\n| 프랑케 | 1690년대 | 할레에서 가난한 아이들을 돌보는 학교를 시작함 |\n| 진젠도르프 | 1722~1727년 | 피난민을 맞아 헤른후트를 이룸. 1727년 여름 옛 형제 교회를 새롭게 한다는 생각을 내세우고 8월 성찬 예배에서 새로워짐 |\n| 에드워즈 | 1734~1746년 | 노샘프턴의 부흥(1734~1735), 『놀라운 회심 이야기』(1737), 『신앙감정론』(1746) |\n| 웨슬리 | 1738~1744년 | 1738년 5월 올더스게이트의 저녁, 1739년 야외 설교, 1744년 첫 연회 |\n| 휫필드 | 1739~1742년 | 영국과 신대륙을 다니며 설교함 |",
