            "h": "마음이 뜨거워진 저녁과 들판의 설교",
            "t": "영국에서 사제로 일하던 웨슬리는 1738년 5월 런던 올더스게이트 거리의 모임에 내키지 않는 걸음으로 갔습니다. 그곳에서 누군가 루터가 로마서에 쓴 머리말을 읽는 소리를 듣다가, 마음이 이상하게 뜨거워졌다고 일기에 적었습니다. 그리스도 한 분만 믿고 맡긴다는 확신이 들었다고 씁니다.³ 그는 곧 모라비아 형제들을 만나러 독일로 떠나기로 했습니다.\n\n이듬해 봄 웨슬리는 브리스톨에서 휫필드가 들판에서 설교하는 것을 보았습니다. 1739년 4월 2일 웨슬리도 브리스톨 가까운 들판에서 처음 야외 설교를 했고, 그날 전한 말씀은 \"주의 영이 내게 임하셨다\"로 시작하는 대목(이사야서와 누가복음에 나옴)이었다고 일기에 적었습니다. 그는 질서와 예의를 오래 소중히 여겨 온 사람이라 처음에는 이 방식이 낯설었다고 씁니다.⁴\n\n휫필드는 1739년부터 1742년 무렵까지 영국과 신대륙을 오가며 설교했고, 여러 곳에서 부흥이라 불린 모임이 일어났다고 전합니다. 뒷날 학자들은 이 시기의 신대륙 부흥을 대각성이라는 이름으로 부릅니다. 웨슬리와 동료들의 모임은 1744년 첫 연회(모여서 가르침과 일을 의논하는 모임)를 열었습니다.",
