                "alt": "2권의 두 줄기(동쪽 교회와 서쪽 교회)가 이어 흐르고, 1517년 뒤 서쪽 교회에서 루터교, 개혁교회, 재세례파 교회들, 성공회가 같은 굵기의 줄기로 갈라져 흐른다. 서쪽 본 줄기(가톨릭 교회)와 동쪽 교회도 계속 흐른다. 서쪽 본 줄기 아래로 침례교, 퀘이커, 경건주의와 부흥이라는 이름의 곁 물길 셋이 짧게 뻗어 있다. 강 위에 1517년, 1563년, 1618년, 1648년, 1730~40년대 이름표가 있고 노란 칠이 12과가 다루는 때(1648~1750년)를 보여 준다. 사람은 없다.",
