            "h": "서로 이해하려 모인 자리들",
            "t": "서쪽 교회들도 마주 앉으려 한 때가 있었습니다. 1529년 10월 마르부르크에서 루터와 츠빙글리와 동료들은 열다섯 조의 글에 서명했고, 성찬의 한 대목을 빼고는 서로 합의했습니다. 1536년 5월에는 비텐베르크에서 루터교 쪽 신학자들과 남독일 도시의 대표들이 성찬에 관한 합의문에 서명했으나, 스위스의 교회들은 선뜻 받아들이지 않았습니다.⁴\n\n1541년 레겐스부르크에서는 가톨릭 쪽 신학자들과 개혁을 바라던 쪽 신학자들이 칭의(하나님이 죄인을 의롭다고 하신다는 가르침)에 관한 글을 함께 만들었습니다. 5월 2일 이 글을 함께 받아들였지만, 교회의 권위 같은 문제에서 막혀 회담은 끝났습니다. 이 글에 대한 평가는 갈렸습니다. 칼뱅은 참된 가르침의 핵심이 남아 있다고 평했고, 루터는 서로 맞지 않는 생각을 이어 붙인 것이라고 평했으며, 가톨릭 쪽의 반응도 엇갈렸다고 전합니다.⁵\n\n1645년 토룬에서는 폴란드 왕의 부름으로 가톨릭과 루터교, 개혁교회의 신학자들이 모였으나 하나의 문안에 이르지 못했습니다.⁶ 한꺼번에 모든 문제가 풀린 자리는 없었다고 전하며, 그 뒤에도 각 교회 가족은 자기를 설명하는 글을 들고 자기 길을 이어 갔습니다.\n\n| 때와 곳 | 모인 사람들 | 구한 것 | 그 뒤(사실만) |\n| --- | --- | --- | --- |\n| 1529년 10월, 마르부르크 | 루터, 츠빙글리와 동료들 | 성찬을 포함한 믿음의 문제에서 서로 이해하기 | 열다섯 조의 글에 서명함. 성찬의 한 대목(빵과 포도주 안에 그리스도의 몸과 피가 몸으로 계시는가)에서는 합의하지 못했고, 서로 사랑하겠다는 다짐으로 글을 맺음 |\n| 1536년 5월, 비텐베르크 | 루터교 쪽 신학자들과 부처, 카피토 등 남독일 도시의 대표 | 성찬에 관한 합의 | 5월 29일 합의문에 서명함. 스위스의 교회들은 선뜻 받아들이지 않음 |\n| 1541년, 레겐스부르크 | 가톨릭 쪽 그로퍼, 에크, 플루크와 개혁을 바라던 쪽 멜란히톤, 부처, 피스토리우스 | 칭의에 관한 함께 쓸 글 | 칭의에 관한 5조는 5월 2일 함께 받아들였으나 교회의 권위 같은 문제에서 막힘 |\n| 1645년, 토룬 | 폴란드 왕의 부름을 받은 가톨릭, 루터교, 개혁교회의 신학자들 | 서로의 차이를 이야기해 보기 | 하나의 문안에 이르지 못함 |"
