            "h": "본문의 자리",
            "t": "요한복음 17장은 예수께서 제자들과 마지막 식사를 나누신 뒤 아버지께 드린 기도입니다. 앞부분에서는 자신과 제자들을 위해 기도하셨고, 20절부터는 마음이 더 멀리 닿습니다. 눈앞의 제자들만이 아니라, 그들이 전하는 말을 통해 믿게 될 사람들까지 품고 기도하십니다.\n\n21~23절에서 예수께서는 이 모든 사람이 하나이기를 구하십니다. 그 하나 됨은 아버지가 아들 안에, 아들이 아버지 안에 계신 모습과 이어집니다. 그들이 하나일 때 세상이 아버지께서 아들을 보내셨음을 알아보게 된다는 이유도 말씀하십니다.\n\n24~26절에서 예수께서는 아버지께서 맡기신 이들이 자신이 있는 곳에서 함께 지내며 아들의 영광을 보기를 바라십니다. 기도는 사랑으로 끝납니다. 아버지가 아들을 사랑하신 그 사랑이 이들에게 머물고, 아들도 이들과 함께하시기를 구하십니다.",
