            "t": "요한복음 10:16에서 예수께서는 이 울타리 밖에도 자기 양들이 있고 그들도 하나의 무리가 될 것이라고 하십니다. 이 말씀은 17장의 기도와 나란히 읽히곤 하며, 그 양들이 누구인지는 풀이가 갈립니다. 13:34~35는 서로 사랑하는 모습으로 세상이 제자를 알아본다고 말합니다.\n\n그리스도를 가리키는 자리는 20~23절입니다. 예수께서는 믿는 모든 사람이 하나가 되기를 아버지께 직접 구하셨습니다.\n\n우리와 같은 것은 웨스트민스터 신앙고백이 보이지 않는 공교회를 모든 때와 곳에서 그리스도 아래 모인 택하신 이들 전체로(25장 1절), 보이는 공교회를 온 세상에서 참된 신앙을 고백하는 사람들과 그 자녀들로(25장 2절) 말한다는 점입니다. 다른 것은 교회마다 자기 교회의 하나 됨을 달리 설명한다는 점이며, 아래 표에 각 교회의 글을 나란히 놓았습니다. 이 책은 이 이야기를 \"한 교회가 여러 집이 된 길\"이라는 비유로 풀었을 뿐 어느 설명이 맞는지는 가리지 않으며, 요한복음 17장의 기도는 그 모든 교회가 함께 들을 수 있는 기도로 남아 있습니다. 우리 교회가 어떤 입장을 더할지는 교역자와 나눕니다.⁷\n\n| 교회 | 자기 교회의 하나 됨을 설명한 글 |\n| --- | --- |\n| 가톨릭 | 『가톨릭교회 교리서』 816~819항: 그리스도의 한 교회가 베드로의 후계자와 그와 하나 된 주교들이 이끄는 가톨릭교회에 온전히 있다고 설명하고, 다른 공동체들 안에도 거룩함과 진리의 요소가 있다고 말함 |\n| 루터교 | 아우크스부르크 신앙고백(1530) 7조: 교회의 하나 됨에는 복음이 바르게 가르쳐지고 성례가 바르게 베풀어지는 것으로 충분하고, 사람이 만든 예식이 같을 필요는 없다고 설명함 |\n| 성공회 | 39개조 19조: 보이는 그리스도의 교회는 하나님의 말씀이 바르게 선포되고 성례가 바르게 베풀어지는 신자들의 모임이라고 설명함 |\n| 정교회 | 예루살렘 회의의 신앙고백(1672) 10조: 교회는 그리스도를 유일한 머리로 하고 사도 때부터 이어진 감독들을 통해 다스려진다고 설명함 |",
